client_script:
frappe.web_form.on('clinic', (field, value) => {
    if (value) {
        frappe.call({
            method: "frappe.client.get_list",  
            args: {
                doctype: "Doctor",  
                filters: {
                    'clinic': value  
                },
                fields: ['name', 'full_name']  
            },
            callback: function(response) {
                let doctor_options = response.message || [];


                let formatted_options = doctor_options.map(option => ({
                    label: option.full_name,  
                    value: option.name        
                }));


                frappe.web_form.fields_dict.doctor.set_data(formatted_options);
            }
        });
    }
});
frappe.web_form.on('date', (field, value) => {
    if (value) {
        var today = frappe.datetime.get_today();
        if (value === today) {
            frappe.web_form.fields_dict.reminder_date.set_value(today);
        } else {
            var reminder_date = frappe.datetime.add_days(value, -1);
            frappe.web_form.fields_dict.reminder_date.set_value(reminder_date);
        }
    }
});

custom_css:
:root{
    --yellow_color:#ffc024;
    --green_color:#01b07a;
    --blue_color:#294a66;
    --discard_btn:#e55934;
    --previous-btn:#0087b9;
}
.web-form-header{
    background-color:var(--yellow_color) !important;
    border: 1px solid  var(--yellow_color) !important;
}
.container .page_content{
    background-color: var(--yellow_color) !important;
}
.web-form-head{
    border-bottom: 1px solid  var(--yellow_color) !important;
}

.btn.btn-default.btn-sm.btn-attach{
    background-color:#f3f3f3 !important;
    font-weight: normal !important;
}
.btn-next,.submit-btn {
    background-color: var(--green_color) !important;
}
.btn-previous{
    background-color: var(--previous-btn) !important;
}
.discard-btn{
    background-color: var(--discard_btn) !important;
}
.btn-primary{
    background-color: var(--green_color) !important;
}
[data-doctype="Web Form"] .page_content {
    max-width: 100% !important;
    margin: auto;
}
.upload-option span {
    font-size: 10px;
    color: #555;
}

.upload-container {
    display: flex;
    justify-content: center;
    align-items: center;
}

.modal-dialog {
    max-width: 800px;
}

.modal-content {
    max-height: 90vh;
    overflow-y: auto;
}

.modal-body {
    display: flex;
    flex-direction: column;
    align-items: center;
}



.controls {
    display: flex;
    justify-content: center;
    gap: 10px;
    flex-wrap: wrap;
}

.button {
    background-color: #0a0a0a;
    border: none;
    color: white;
    padding: 10px 20px;
    border-radius: 5px;
    cursor: pointer;
    font-size: 14px;
    transition: background-color 0.3s, transform 0.2s;
}

.button:hover {
    background-color: #45a049;
    transform: scale(1.05);
}

.button:disabled {
    background-color: #ccc;
    cursor: not-allowed;
}



@keyframes flash {
    0% { opacity: 1; }
    50% { opacity: 0.5; }
    100% { opacity: 1; }
}

.loading-screen {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.7);
    color: white;
    border-radius: 5px;
    z-index: 1000;
    display: flex;
    justify-content: center;
    align-items: center;
    text-align: center;
}

/* Responsive Fixes */
@media (max-width: 480px) {
    .controls {
        flex-direction: column;
        align-items: center;
        gap: 8px;
    }

    .button {
        width: 100%;
    }

    .modal-dialog {
        margin: 10px;
    }
}


@keyframes spin {
    0% { transform: rotate(0deg); }
    100% { transform: rotate(360deg); }
}

/* Circular progress container */
#uploadProgressCircle {
    border-radius: 50%;
    background: conic-gradient(#4caf50 0%, #f3f3f3 0%);
    border: 8px solid #f3f3f3;
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 80px;
    height: 80px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 14px;
    color: #4caf50;
}
